mapper.select:
SELECT cm.car_id AS carId, m.maker_name AS maker, mo.model_name AS model, t.trim_name AS trim, cm.year AS year, cm.mileage AS mileage, COALESCE(MIN(pc.price), 0) AS price, COALESCE(MAX(pc.fuel), cm.fuel) AS fuel, COALESCE(MAX(pc.transmission), cm.transmission) AS transmission, COALESCE(MAX(pc.color), cm.color) AS color, COALESCE(MAX(pc.region), cm.region) AS region FROM car_master cm LEFT JOIN platform_car pc ON pc.car_id = cm.car_id LEFT JOIN cz_maker m ON m.maker_code = cm.maker_code LEFT JOIN cz_model mo ON mo.maker_code = cm.maker_code AND mo.model_group_code = cm.model_group_code AND mo.model_code = cm.model_code LEFT JOIN cz_trim t ON t.maker_code = cm.maker_code AND t.model_group_code = cm.model_group_code AND t.model_code = cm.model_code AND t.trim_code = cm.trim_code WHERE cm.adv_status IN ('ONSALE', 'ADVERTISE')
AND cm.model_code IN #{code}
GROUP BY cm.car_id, m.maker_name, mo.model_name, t.trim_name, cm.year, cm.mileage, cm.fuel, cm.transmission, cm.color, cm.region ORDER BY cm.car_id LIMIT #{limit}

SELECT model_code AS code, model_name AS name
FROM cz_model
WHERE MAKER_CODE = #{makerCode}
  AND model_group_code = #{modelGroupCode}
ORDER BY name

SELECT trim_code AS code, trim_name AS name
FROM cz_trim
WHERE MAKER_CODE = #{makerCode}
  AND model_group_code = #{modelGroupCode}
  AND MODEL_CODE = #{modelCode}
ORDER BY name

SELECT grade_code AS code, grade_name AS name
FROM cz_grade
WHERE MAKER_CODE = #{makerCode}
  AND model_group_code = #{modelGroupCode}
  AND MODEL_CODE = #{modelCode}
  AND TRIM_CODE = #{trimCode}
ORDER BY name
